	title 'Tool Locator--Tool Loading'*****************************************************************			   **	   Tool Loading		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1989	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   ***************************************************************************************************************************************** Change History** 15 Mar 89	Steven Glass** UnloadThisTool no longer can cause a system death.  It used to* die on unexpected loader errors.  There are now just ignored.** 07 Apr 89	Steven Glass** Added range check to UnloadThisTool** 4/6/90	Mensch* Fixed range check in UnloadThisTool it will now correctly test the* current TPT.** 18-Nov-90	Dave Lyons** Changed CheckVersion to reflect new definition of version bits 14-12.* These flag special things about the tool version.** 3-Dec-91	Dave Lyons** Changed LoadThisTool to always prompt for boot disk (state of Cancel* button is not forced).** 16-Dec-91	Dave Lyons** Fixed capitalization of StartChars string (*/System/Tools/Tool),* since the Loader now makes the original capitalization visible* through LGetPathname[2].** Added ReportIfMissing to LoadTools, to tell user what tool they* need to install.** 17-Dec-91	Dave Lyons** Changed Quit to Continue in ReportIfMissing.************************************************************************* 7-Jul-92	Dave Lyons for 6.0.1** Changed ReportIfMissing to never complain that a tool that is* present is missing just because the version is too low.***********************************************************************	blanks off	string asis	print push	print off	include 'all.macros'	include '::sys.equs.asm'	INCLUDE 'e16.memory'	include 'tl.equates.asm'	print pop	title ' Imported Addresses';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT BusyErr4	eject*****************************************************************LoadTools	PROC EXPORT**         Pointer to ToolTable** where ToolTable looks**              dc i'NumTools'*              dc i'ToolNum1,MinVersion1'*              dc i'ToolNum2,MinVersion2'*              .*              .*              .*** The tools are kept in the subdirectory TOOLS in the system* subdirectory with	the following naming convention:**          Tool015	 for tool set 15*          Tool023	 for tool set 23** etc.** Tools 1 through 13 are in ROM.  The only parts of them that* will be in RAM are not loaded in this	way but are part of	the* patch mechanism.***** Inputs:*	ToolTablePtr : Long** Outputs:*	none** External Refs:	import GetSpecialFlag	import LoadThisTool	import ReportIfMissing	;16-Dec-91 DAL** Entry Points:*	none*	longa on	; mode	longi on** Change History** 05 Oct 87    Steven Glass**    Changes were made to this call to accomdate new calling*    structure for LoadThisTool.  Additionally, changes were*    made to get rid of the special memory global variable.**    Finally, this call was adjusted to	use the new exit*    routines.*****************************************************************	DefineStackCounter	wordSpecialFlag	wordCurPtr	longOrigD	wordRTL1	block 3RTL2	block 3ToolTablePtr	long	phd	; save direct	lda #0	; put eight extra bytes on stack	pha	; (all zeros)	pha	pha	pha	tsc	; get stack	tcd	; set stack to zp	jsl IncBusyFlg	phb	; save and set data	bank	phk	plb	jsr GetSpecialFlag	; init the special flag.	sta SpecialFlag	lda ToolTablePtr	; init CurPtr	clc	adc #2	sta CurPtr	lda ToolTablePtr+2	adc #0	sta CurPtr+2Loop	lda Counter	; test counter to see if we are	cmp [ToolTablePtr]	; done.	bcs AllDone	pha	; space for result	lda [CurPtr]	; Push Tool Number	pha	ldy #2	; Push min version from table	lda [CurPtr],y	; 	pha	pei SpecialFlag	jsr LoadThisTool	; get it loaded	plx	stx SpecialFlag	bcs ErrorOut	; if error occured,	quit.	lda CurPtr	; bump pointer into	table	clc	adc #4	sta CurPtr	lda CurPtr+2	adc #0	sta CurPtr+2	inc Counter	; bump counter	bra LoopAllDone		; 	lda #0	; signal no error and fall into;		; error out routineErrorOut	plb	; restore DBR	tax*** added 16-Dec-91 DAL -- put up a nice missing-tool dialog	lda [CurPtr]	jsr ReportIfMissing*** end 16-Dec-91	ply	; clean up the stack	ply	ply	ply	jml BusyErr4	ENDP****************************************************************** ReportIfMissing -- new routine 16-Dec-91 DAL for 6.0d62** Input: A = tool number, X = error code** Registers are preserved.*****************************************************************ReportIfMissing	proc export	cpx #$0046	;file not found?	bne @noMessage	pha	phx	phy*** added 7-Jul-92 DAL -- Don't complain that a loaded tool is missing just***                       because the version is too low.	lda 5,s	;tool number	ora #$0400	;xxxVersion	tax	pha	;space for result	jsl $e10000	pla	;discard result	bcc @noMsg	lda 5,s*** end 7-Jul-92	pha	;tool # for Int2Dec	pushlong #toolNumTxt	pea 3	;3 character length	pea 0	;unsigned	_Int2Dec	sep #$20	longa off	lda >toolNumTxt+0	cmp #$20	;blank	bne @notBlank1	lda #$30	;zero	sta >toolNumTxt+0@notBlank1	lda >toolNumTxt+1	cmp #$20	;blank	bne @notBlank2	lda #$30	;zero	sta >toolNumTxt+1@notBlank2	rep #$20	longa on	pha	;space for TLTextMountVol result	pushlong #missingLine1	pushlong #missingLine2	pushlong #nullText	pushlong #OKStrText	_TLTextMountVolume	pla	;discard result@noMsg	ply	plx	pla@noMessage	rtsmissingLine1	dc.b 30,'This application needs Tool'toolNumTxt	dc.b '000'missingLine2	dc.b 27,'in the System:Tools folder.'; text OK button string for TLTextMountVolume; spaces push Button2 (left button) to the right (to right-justify it);   (canÕt be Button1 because escape chars are counted in Button1Õs right justification!); $1B: ESC to enable mousetext in the firmware; $0F: turns on Inverse; ÔMÕ is mousetext for return char; $0E: turns off inverse; $18: Ctrl-X to disable mousetext in the firmwareOKStrText	dc.b EndOKStrText-*-1,'                       Continue '	dc.b $0f,$1b,'M',$0E,$18EndOKStrTextnullText	dc.b 0	EndP	title 'LoadOneTool'*****************************************************************LoadOneTool	PROC EXPORT** Assures that the specified tool is available and has a version * number equal to or greater than MinVersion.  If the tool is not* loaded when the call is made it trys to load the tool from disk.** If the tool is not on disk or the required version is not available* errors are returned.*** Inputs:*         ToolNumber : word*         MinVersion : word** Outputs:*	none** External Refs:	import GetSpecialFlag	import LoadThisTool** Entry Points:*	none*	longa on	; mode	longi on*** Change History**   05 Nov 86   SEG	   The Stack equates were off by one.  The*	   data bank register was not accounted	for.**   05 Oct 87   SEG	   Uses direct page	addressing instead of *	   stack.**	   Uses new format of LoadThisTool call.**	   Uses new exit routines.**   14 Oct 87   SEG	   Extra D-reg no longer left on stack.*****************************************************************	DefineStackOrigD	wordRTL1	block 3RTL2	block 3MinVersion	wordToolNumber	word	phd	; save direct	tsc	; get stack	tcd	; set stack to zp	jsl IncBusyFlg	phb	phk	plb	pha	; space for result	pei ToolNumber	pei MinVersion	jsr GetSpecialFlag	pha	jsr LoadThisTool	; get it loaded	plx	; ignore the result	plb	; restore dbr	tax	; error code in x	jml BusyErr4	ENDP	title 'UnloadOneTool'*****************************************************************UnLoadOneTool	PROC EXPORT** Unloads the specified tool in the following way:  If it was* loaded from disk it calls the Loader to put it in zombie state* and installs a dummy tool table for the specified tool.** If the tool was not loaded from disk, this proc does nothing.*** Inputs:*	ToolNumber : integer** Outputs:*	none** External Refs:	import SetupForUnload	import CleanupForUnload	import UnloadThisTool** Entry Points:*	none*	longa on	; mode	longi on** Change History** 05 Oct 87    Steven Glass**    This call was adjusted to use the new exit routines.**    No changes were need to make this run in ROM.  Many changes*    were made however to adjust this to the new tool loading*    algorithm.  *****************************************************************RTL1	equ 1RTL2	equ RTL1+3ToolNumber	equ RTL2+3	jsl IncBusyFlg	lda ToolNumber,s	DefineStackOrigD	wordRealTPT	longDefaultTPT	longCounter	word	jsr SetupforUnload	; preserves a-reg	sta Counter	jsr UnloadThisTool	jsr CleanupForUnload	tax	ldy #2	jml ToBusyStrip	ENDP	title 'SetDefaultTPT'*****************************************************************SetDefaultTPT	PROC EXPORT** Makes the current TPT the default TPT by making a copy of it.* To do this we first size the default TPT, then copy the * real TPT to the default one.*** Inputs:*	none** Outputs:*	none** External Refs:	import SetupForUnload	import CleanupForUnload	import TLGetMem** Entry Points:*	none*	longa on	; mode	longi on** Change History** 05 Oct 87    Steven Glass**    This call was added to support new	tool loading algorithm.*****************************************************************	DefineStackOrigD	wordRealTPT	longDefaultTPT	longCounter	word;---------------------------------------------------;; Set things up.  Inc busy flag and use	same routine; as used for unloading to setup stack as d-page.;	jsl IncBusyFlg	jsr SetupForUnload;---------------------------------------------------;; First make the default table the same	size as; the real table.;	lda DefaultTPT	ora DefaultTPT+2	beq NoneToDispose	pha	; start by finding the handle	pha	; to the default tpt memory	pei DefaultTPT+2	pei DefaultTPT	_FindHandle	_DisposeHandle	; and disposing itNoneToDispose	lda [RealTPT]	; Now get size of the real	asl a	; tpt by taking num	entries	asl a	; times 4	ldx #attrNoSpec+attrLocked ; Get handle	of this size and 	jsr TLGetMem	; these attributes	sta DefaultTPT	; Deref handle and put ptr	stx DefaultTPT+2	; in place.	lda [DefaultTPT]	tax	ldy #2	lda [DefaultTPT],y	sta DefaultTPT+2	sta >DefaultTPTPtr+2	stx DefaultTPT	txa	sta >DefaultTPTPtr;---------------------------------------------------;; Now copy the contentes of the real table to the; default table.;	lda [RealTPT]	asl a	asl a	tay	dey	deyLoop	lda [RealTPT],y	sta [DefaultTPT],y	dey	dey	bpl Loop;---------------------------------------------------;; Clean everything up.;	jsr CleanupForUnload	ldx #0	ldy #0	jml ToBusyStrip	ENDP	title 'GetSpecialFlag'*****************************************************************GetSpecialFlag	PROC** Returns value of SpecialMemory flag in a-reg.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 05 Oct 87    Steven Glass**    This call no longer sets a global variable, but rather*    returns with the value fo that variable in the a-reg.**    The name of this routine was changed from SetSpecialFlag*    to GetSpecialFlag.*****************************************************************	pha	pha	_TotalMem	pla	pla	cmp #^256*1024	beq BaseMachine	pha	pha	_FreeMem	pla	pla	cmp #^200*1024	bcc NotEnough	lda #$8000	rtsNotEnough		; BaseMachine		; 	lda #0	rts	ENDP	title 'LoadThisTool'*****************************************************************LoadThisTool	PROC*** Loads the tool, installs it, checks its version number * against the min required.** How its done**     Version is checked for desired tool.  If the currently installed*     tool has a good enough version number, we are done.  If the version *     number is bad or the tool is not installed we try and load*     the tool from disk as follows:**       First try a restart in case the tool is alread in memory.  If this*       works, install the tool, do the version check and quit**       If the tool cannot be restarted, create the pathname *       of the the tool to load.**       Use the specialFlag to decide how to load the tool (special*       mem or not).  If a non special mem load fails, try again in *       special.**       Install the TPT that is at the start of the load file.**       Verify the version number.**     Many different errors can be returned:**       Any loader errors including volume not found and not enough memory.*       The version error can also be returned.**** Inputs:*     ToolNumber	           : word*     MinVersion	           : word*     SpecialFlag	           : word** Outputs:*     NewValue of SpecialFlag  : word** External Refs:	import TLGetMem	import MakeIDNum** Entry Points:*	none*	longa on	; mode	longi on** Change History** 29 January 87    Steven Glass**    When a prodos error occured I was comparing the error code to $0201*    (memfull).  When not equal I was trying to exit with error code in*    A-reg but compare cleared carry causing all sorts of grief.*** 05 Oct 87    Steven Glass**    Adjustments were necessary to run out of ROM.*    This routine now has inputs and outputs on the stack.	It*    does not use inline data storage.**    Version checking is now in-line rather than a subroutine*    call.  This made it possible to share local variables*    and since no other routine was using this code, it saved*    the JSR/RTS.**    MakeToolPath is now part of this routine.  It was never*    called by any other routine and making it part of this*    routine makes it easier to share local data.**    The tool path name is now created in a handle rather than*    in line.  The handle is obtained by MakeToolPath and*    disposed of during clean up.*****************************************************************	DefineStackPathHandle	longPathPtr	longOrigD	wordRTSAdr	wordTheSpecialFlag	wordTheMinVersion	wordTheToolNumber	wordResultSpecialFlag	word;---------------------------------------------------;; Save, direct reg,	get space for locals and ; turn stack into direct page.;	phd	; save direct	lda #0	; put zeros on stack	pha	; for path handle and	pha	; ptr	pha	pha	tsc	; turn stack into 	tcd	; direct page;---------------------------------------------------;; Check to see if this is a tool we have to load.; If the version number checks out then	there is; nothing else to do.  If the version does not; check out, then try to load it from the ; system disk.;	jsr CheckVersion;;;	bcc FastExit	bcs @noFastExit	brl FastExit@noFastExit*** added 3-Dec-91 DAL -- prompt for boot disk if needed	_GetSysPrefsGS oldPrefs	lda >oldPrefs+2	and #$5fff	;keep the reserved bits and the Cancel state	ora #$8000	;turn on Use Volume Mount Dialog	sta >myPrefs+2	_SetSysPrefsGS myPrefs*** end 3-Dec-91	lda <TheToolNumber	; line added 18-Nov-90 DAL	cmp #17	; the loader is never loaded	beq DoNotLoad	; from disk;---------------------------------------------------;; Try Restart, just	in case it is already in ; memory.;	lda TheToolNumber	jsr MakeIDNum	phx	; space for zp segment size	phx	; space for zp segment starting address	phx	; space for starting address	phx	phx	; make space for returning user id	pha	; push the id of the tool	_RESTART	bcc SkipInitialLoad	pla	; clear off junk id	pla	; clear off junk starting addr	pla	pla	; clear off junk zp	seg	pla	; clear off junk zp	size;---------------------------------------------------;; Restart failed, so make pathname of tool to load;	jsr MakeToolPath	; make tool path uses ts num in a-reg	bcs LoadError;---------------------------------------------------;; First look at the	SpecialFlag.  If it	is clear; then don't try to	load outside of special memory; (we already know that it won't work).;	ldx TheSpecialFlag	beq TooSmall	jsr DoInitialLoad	; load into non special memory	bcc LoadOK	cmp #MemFullError	bne LoadError	stz TheSpecialFlag	; don't try this again	ldx TheSpecialFlagTooSmall	jsr DoInitialLoad	bcs LoadError	bcc LoadOK;---------------------------------------------------;; Restart was successful, make stack look same; as if called DoInitialLoad.;SkipInitialLoad	pla	; don't need user id	plx	; need starting addr	ply	pla	; don't need zp adr	pla	; don't need zp sizeLoadOK;---------------------------------------------------;; Install the tool;	PushWord #0	; System Flag	pei TheToolNumber	; Tool number	phy	; Table Address	phx	_SetTSPtr	bcs InstallErrorDoNotLoad	jsr CheckVersion	; any error will be	in a-reg;---------------------------------------------------;; Copy the final value for SpecialFlag from to; result word, and clean up the stack.LoadErrorInstallError*** added 3-Dec-91 DAL -- restore OS preferences	pha	;save error code	_SetSysPrefsGS oldPrefs	pla	;retrieve error code*** end 3-Dec-91FastExit	ldx TheSpecialFlag	stx ResultSpecialFlag	pha	; save the error code	lda PathHandle	ora PathHandle+2	beq NoHandle	pei Pathhandle+2	pei Pathhandle	_DisposeHandleNoHandle	pla	; get error code	plx	; strip off 4 words	of local vars	plx	plx	plx	pld	; restore direct page	ply	; get rts adr in y-reg for momment	plx	; pull 3 input words off stack	plx	plx	phy	; put rts adr back on stack	cmp #1	; set carry based on error code	rts*** added 3-Dec-91 DALoldPrefs	dc.w 1	;1 parameter	dc.w 0	;the old SysPrefsmyPrefs	dc.w 1	dc.w 0	;my modified preferences*** end 3-Dec-91;---------------------------------------------------;; Local routine to handle making the intial load; call.;; Inputs:;    TheToolNumber;    TheSpecialFlag;; Outputs:;    x-reg   Low word of address of tool;    y-reg   High word of address of tool;    a-reg   Error code from InitialLoad call;    carry   set if	error, clear if none.;    ;DoInitialLoad	lda TheToolNumber	; get ID num back	jsr MakeIDNum	phx	; space for zp segment size	phx	; space for zp segment starting address	phx	; space for starting address	phx	phx	; space for userid	pha	; Push the Tools userID	pei PathPtr+2	; Push pointer to the path name	pei PathPtr	pei TheSpecialFlag	; special memory flag	_InitialLoad	sta 9,s	; save any error over zp size on stack	pla	; don't need user id	plx	; need starting addr in x,y	ply	pla	; don't need zp adr	pla	; put error (if any	back in a-reg)	rts*** old way  18-Nov-90 DAL*** old way*** old way	CheckVersion*** old way	;---------------------------------------------------*** old way	;*** old way	; Check the version	of the tool installed to*** old way	; be sure it is high enough.*** old way	;*** old way	; The Tool Set number and the Min required version are*** old way	; on direct page.*** old way	;*** old way	; I use the tool set number to make a version call.  If an error*** old way	; occurs, I return it.*** old way	;*** old way	; Using the version	number that has returned, I mask off the*** old way	; high bit and start comparing.*** old way	;*** old way	; If the major part	of the version number is greater than the*** old way	; minimum required version, the compare	is complete.  If the*** old way	; major part of the	version number is the same as the required*** old way	; version number then I go on to compare the minor part.*** old way	;*** old way	*** old way	TempStorage	equ 3*** old way	RealVersionNum	equ 1*** old way	*** old way		pha	; space for temp storage.*** old way		pha	; space for version	call result.*** old way		lda TheToolNumber	; get tool number and make into*** old way		ora #$0400	; version call*** old way		tax*** old way		jsl $E10000	; (this will be RealVersion)*** old way		bcs FixStack*** old way	*** old way		lda RealVersionNum,s ; clear the high bit that means*** old way		and #$7FFF	; prototype*** old way		sta RealVersionNum,s*** old way		and #$FF00	; start with major version*** old way		sta TempStorage,s*** old way	*** old way		lda TheMinVersion	; get desired version*** old way		and #$FF00*** old way		cmp TempStorage,s*** old way		bcc AllIsWell*** old way		beq CheckMinor*** old way	*** old way	VersionError	lda #BadVersionNum*** old way		bra FixStack*** old way	*** old way	CheckMinor	lda RealVersionNum,s ; get the minor part*** old way		and #$00FF*** old way		sta TempStorage,s*** old way		lda TheMinVersion*** old way		and #$00FF*** old way		cmp TempStorage,s*** old way		beq AllIsWell*** old way		bcs VersionError*** old way	*** old way	;---------------------------------------------------*** old way	;*** old way	; The version checked out okay.  Set error code*** old way	; to zero and fall into clean up code.*** old way	;*** old way	*** old way	AllIsWell		; *** old way		lda #0	; No Error*** old way	*** old way	FixStack	plx*** old way		plx*** old way	*** old way		cmp #1*** old way		rts************************************************************************************ CheckVersion* 18-Nov-90 DAL** Inputs:  TheToolNumber, TheMinVersion** Output:  carry flag = clear if we're okay*          A = error code** Version Number format:**  ---------------------------------*  |P|f|f|f|m|m|m|m|v|v|v|v|v|v|v|v|*  ---------------------------------*      P = prototype bit*      f = flag bits*      m = major version*      v = minor version** The Prototype bit is ignored in version comparisons.** The Flag bits are handled specially.  If you don't* ask for a given flag, it doesn't affect the comparison* at all.  But if you ask for one, it's required in the* actual version.*CheckVersion	pha	; space for version	call result	lda TheToolNumber	; get tool number and make into	ora #$0400	; version call	tax	jsl $E10000	; (this will be RealVersion)	bcc @1	plx	;pull result space	rts@1	pla	tay	;Y=copy of real version	and #$7000	eor #$7000	;Which flag bits are actually off?	and <TheMinVersion	;Did we need any of them?	bne @VersionError	;Oops, we did.	lda <TheMinVersion	and #$0fff	pha	tya	;Get real tool version back	and #$0fff	;check major and minor versions	cmp 1,s	pla	bcs @AllIsWell	;Version is at least equal to MinVersion@VersionError	lda #BadVersionNum	sec	rts@AllIsWell	lda #0	; No Error	clc	rts;---------------------------------------------------;; MakeToolPath;; 1.  Gets memory to hold a pathname.  Handle;     is put into PathHandle, and derefed into;     PathPtr.; 2.  Creates the path in PathHandle;;MakeToolPath;---------------------------------------------------;; First get memory and deref the handle.;	lda #PathSize	ldx #attrLocked	jsr TLGetMem	bcc GotIt	rtsGotIt	sta PathHandle	stx PathHandle+2	lda [PathHandle]	sta PathPtr	ldy #2	lda [PathHandle],y	sta PathPtr+2;---------------------------------------------------;; Now copy the first part of the path name into; the memory we've obtained.;	phb	; set bank to this code bank	phk	plb	sep #$30	; switch to 8 bit mode	longa off	longi off	ldy #PathSize-1	; move the stringMoveLoop	lda |ToolPath,y	sta [PathPtr],y	dey	bpl MoveLoop	rep #$30	; back to full native	longa on	longi on	plb	; restore dbr.;---------------------------------------------------;; Finish up the path name by converting	the tool; number into ascii	characters at the end of the; path name.	pei TheToolNumber	; push the int	lda PathPtr	clc	adc #o_OutChars	tax	lda PathPtr+2	bcc NoCarry	inc aNoCarry	pha	phx	PushWord #3	; 3 character output	PushWord #0	; unsigned	_Int2Dec;---------------------------------------------------;; Fix the path string so that any blanks left; by _Int2Dec are converted to zeros.;	sep #$30	longa off	longi off	ldy #o_OutChars	lda [PathPtr],y	cmp #' '	bne NoMoreBlanks	lda #'0'	sta [PathPtr],y	iny	lda [PathPtr],y	cmp #' '	bne NoMoreBlanks	lda #'0'	sta [PathPtr],yNoMoreBlanks	rep #$30	longa on	longi on	clc	; signal no error	rtsToolPath	DC.B PathLengthStartChars	DC.B '*/System/Tools/Tool'o_OutChars	equ *-ToolPathPathLength	equ *-StartChars+3PathSize	equ PathLength+1	ENDP	title 'UnloadTools'*****************************************************************UnloadTools	PROC EXPORT** The Default TPT is restored.  Any tools that are active * but not part installed in the default	TPT are made into* zombies.**** Inputs:*	none** Outputs:*	none** External Refs:	import MakeIDNum	import DummyTable** Entry Points:	ENTRY UnloadThisTool	ENTRY SetupForUnload	ENTRY CleanupForUnload*	longa on	; mode	longi on** Change History** 05 Oct 87    Steven Glass**    No changes were need to make this run in ROM.*    However, many chnages were made to	this routine because*    we changed the	UnloadTools algorithm.**    In the original version of this routine, all tools not*    in the original rom (1-13) except the loader (17) were*    unloaded.  That is a user shutdown	call was made on *    them to put them in zombie state and a dummy call table*    was installed.**    In this version we do a little more work.  The idea here*    is to restore the "default" TPT.  ** 14 Oct 87    Steven Glass** The loader (tool 17) is never unloaded.*** 15 Mar 89	Steven Glass** _UserShutdown returns some undocumented errors that can* really cause trouble so we just now ignore all errors.** 07 Apr 89	Steven Glass** Added range check to UnloadThisTool so that DummyTable would* not be stored beyond the end of the real tpt if an unload call is* made for a tool not in the defaultTPT.*****************************************************************	DefineStackOrigD	wordRealTPT	longDefaultTPT	longCounter	word;---------------------------------------------------;; Set things up.;	jsr SetupforUnload	; set up direct page	lda #1	; init the counter	sta Counter;---------------------------------------------------;; Loop through each	tool installed.;Loop		; 	lda Counter	; Check to see if we are done.	cmp [RealTPT]	bcs Done	jsr UnloadThisTool	; no so unload this	one	inc counter	; bump the counter	bra LoopDone;---------------------------------------------------;; Update the count in the real table from the; default table.  Note that the default	TPT may; never be bigger than the real TPT.;	ldy #0	jsr MoveToReal;---------------------------------------------------;; Clean things up.;	jsr CleanupForUnload	rts;---------------------------------------------------;; UnloadThisTool;; Input;    Counter  ToolNumber;; This is the routine that does the work for each; tool to be unloaded.;UnloadThisTool	lda Counter	cmp #17	; is it the loader?	bne continue	; No, so go on	rts	; never unload the loader.continue	cmp [DefaultTPT]	; is it in the default table?	bcc InDefaultTable;; See if the tool is in the real table.  07 Apr 89  SEG;; 4/6/90	Mensch; Fixed instruction below, was [RealTPT],y ....;	cmp [RealTPT]	bcc ItsIn	rtsItsIn;---------------------------------------------------;; This tool is not in the default table	so ; install the dummy	table into the real	TPT;	lda Counter	asl a	asl a	tay	lda #DummyTable	sta [RealTPT],y	lda #^DummyTable	iny	iny	sta [RealTPT],y	bra ShutItDown;---------------------------------------------------;; This tool is in the default table.  If it is ; pointer is not the same in the real and the default; then copy from default to real and shut the tool; down.;InDefaultTable	lda Counter	asl a	asl a	tay	lda [DefaultTPT],y	cmp [RealTPT],y	bne Adjust	iny	iny	lda [DefaultTPT],y	cmp [RealTPT],y	bne Adjust	lda #0	;no error (added 26-Nov-90 DAL)	rtsAdjust	lda Counter	; use counter to create table	asl a	; offset used as input to 	asl a	; movetoreal.	tay	jsr MoveToRealShutItDown		; ; If the OS_Kind is not P16 then we skip this part.	lda >OS_Kind	and #$0001	beq SkipShutDown	pha	; space for result	lda Counter	jsr MakeIDNum	pha	; ID to shut down	PushWord #$4000	; leave me in memory as a ZOMBIE	_UserShutdown	; ignore errors	plx	; clear stack from user shutdown callSkipShutDown	rts;---------------------------------------------------;; SetupForUnload;; Routine to setup stack and d-page for	unloading ; tools.  Must be ballenced by a CleanupForUnload; call.;; Note that the a-reg is preserved by this routine.;SetupForUnload		;       	plx	; get rts adr in x.	tay	; preserve the a-reg	pha	pha	pha	pha	pha	phd	tsc	tcd	lda >TPTPtr	sta RealTPT	lda >TPTPtr+2	sta RealTPT+2	lda >DefaultTPTPtr	sta DefaultTPT	lda >DefaultTPTPtr+2	sta DefaultTPT+2	phx	; put rts adr back.	tya	rts;---------------------------------------------------;; CleanupForUnload;; Cleans up the stack and d-page after unload calls.; Must follow a SetupForUnload call.; ; Preserves the a-reg.;CleanupForUnload	plx	pld	ply	ply	ply	ply	ply	phx	rts;---------------------------------------------------;; MoveToReal;; Copies 4 bytes from the DefaultTPT to	the RealTPT; starting from the	byte indicated by the y-reg.;MoveToReal	lda [DefaultTPT],y	sta [RealTPT],y	iny	iny	lda [DefaultTPT],y	sta [RealTPT],y	rts	ENDP*****************************************************************MakeIDNum	PROC** Using the tool number in the a-register, return a* UserID for the Loader to use for the tool.*** Inputs:*	a-reg : tool num** Outputs:*	a-reg : UserID for tool.** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 05 Oct 87    Steven Glass**    No changes were needed to make this run in ROM.*****************************************************************	and #$00FF	; mask off high word	ora #$4000	; or in word for tools	rts	ENDP	END